def length_of_lis(heights):
    """
    Returns the length of the longest increasing subsequence in heights.
    """
    if not heights:
        return 0

    n = len(heights)
    # Create a list to store the length of the longest increasing subsequence ending at each index.
    lis = [1] * n

    # Iterate through the heights and compute the length of the longest increasing subsequence.
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # The maximum value in lis will be the length of the longest increasing subsequence.
    return max(lis)

