def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes(start, end):
    """
    Returns the sum of all prime numbers in the inclusive range [start, end].
    If there are no primes in the range, returns 0.
    """
    return sum(n for n in range(start, end + 1) if is_prime(n))

