def earliest_path_day(m, n, cells):
    """
    Returns the earliest day on which there is a path from the top row to the bottom row.
    """
    parent = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    top_roots, bottom_roots = set(), set()
    for day, (r, c) in enumerate(cells):
        parent[(r, c)] = (r, c)
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (nr, nc) in parent:
                union((r, c), (nr, nc))

        if r == 0:
            top_roots.add(find((r, c)))
        if r == m - 1:
            bottom_roots.add(find((r, c)))

        if any(find(top) in bottom_roots for top in top_roots):
            return day + 1

    return -1

