def is_alien_sorted(words, order):
    """
    Determines if the given words are sorted according to the provided alien alphabet order.

    :param words: List of strings
    :param order: A string representing the alien alphabet order
    :return: True if words are sorted according to the order, False otherwise
    """
    order_index = {char: idx for idx, char in enumerate(order)}

    def compare(word1, word2):
        for c1, c2 in zip(word1, word2):
            if order_index[c1] < order_index[c2]:
                return True
            elif order_index[c1] > order_index[c2]:
                return False
        return len(word1) <= len(word2)

    for i in range(len(words) - 1):
        if not compare(words[i], words[i + 1]):
            return False
    return True

