def max_collectible_rain(nums):
    """
    Returns the maximum amount of rain that can be collected between two days, 
    given that there is a day with no rain between the two selected days.

    :param nums: List[int] - Array representing the amount of rain in millimeters for each day
    :return: int - Maximum amount of rain collectible between two days
    """
    max_rain = 0

    n = len(nums)

    for i in range(n):
        if nums[i] == 0:
            for j in range(i+1, n):
                if nums[j] == 0:
                    if j - i > 1:
                        rain_sum = max(nums[i+1:j])
                        if rain_sum > max_rain:
                            max_rain = rain_sum
                    break

    return max_rain

