def shortest_special_subsequence(nums, target):
    n = len(nums)
    if n < 2:
        return -1

    min_len = float('inf')
    found = False

    # Loop through each pair of elements (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            score = abs(nums[j] - nums[i])
            if score == target:
                found = True
                min_len = min(min_len, j - i + 1)

    return min_len if found else -1

