def count_k_length_substrings_with_no_repeats(s, k):
    """
    Count the number of substrings of length `k` in `s` that have no repeated characters.

    :param s: The input string.
    :param k: The length of the substrings to consider.
    :return: The number of substrings of length `k` with no repeated characters.
    """
    if k > len(s):
        return 0

    count = 0
    char_map = {}
    start = 0

    for end in range(len(s)):
        end_char = s[end]
        if end_char in char_map:
            char_map[end_char] += 1
        else:
            char_map[end_char] = 1

        while char_map[end_char] > 1:
            start_char = s[start]
            start += 1
            char_map[start_char] -= 1
            if char_map[start_char] == 0:
                del char_map[start_char]

        if end - start + 1 == k:
            count += 1
            start_char = s[start]
            start += 1
            char_map[start_char] -= 1
            if char_map[start_char] == 0:
                del char_map[start_char]

    return count

