def count_distinct_substrings(s):
    """
    Returns the number of distinct substrings in the given string s.
    """
    n = len(s)
    substrings_set = set()

    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            substrings_set.add(substr)

    return len(substrings_set)

