def largest_empty_square(board):
    """
    Returns the side length of the largest square sub-grid consisting entirely of 0s.

    :param board: List[List[int]], a k x k board of cells represented by 0 (empty) and 1 (occupied)
    :return: int, the side length of the largest possible square of empty cells
    """
    if not board or not board[0]:
        return 0

    k = len(board)
    dp = [[0] * k for _ in range(k)]
    max_side = 0

    for i in range(k):
        for j in range(k):
            if board[i][j] == 0:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

