def find_median_sorted_arrays(arr1, arr2):
    """
    Finds the median of two sorted arrays.

    Parameters:
        arr1 (list): First sorted array.
        arr2 (list): Second sorted array.

    Returns:
        float: Median of the combined sorted arrays.
    """
    def find_median_util(A, B):
        m, n = len(A), len(B)
        if m > n:
            A, B, m, n = B, A, n, m
        if n == 0:
            raise ValueError("Both arrays are empty")

        imin, imax, half_len = 0, m, (m + n + 1) // 2
        while imin <= imax:
            i = (imin + imax) // 2
            j = half_len - i
            if i < m and A[i] < B[j-1]:
                imin = i + 1
            elif i > 0 and A[i-1] > B[j]:
                imax = i - 1
            else:
                if i == 0: max_of_left = B[j-1]
                elif j == 0: max_of_left = A[i-1]
                else: max_of_left = max(A[i-1], B[j-1])
                if (m + n) % 2 == 1:
                    return max_of_left

                if i == m: min_of_right = B[j]
                elif j == n: min_of_right = A[i]
                else: min_of_right = min(A[i], B[j])

                return (max_of_left + min_of_right) / 2.0

    return find_median_util(arr1, arr2)

