def search_range(nums, target):
    """
    Finds the first and last position of target in sorted nums.
    """
    def find_bound(nums, target, is_first):
        start, end = 0, len(nums) - 1
        bound = -1

        while start <= end:
            mid = (start + end) // 2

            if nums[mid] == target:
                bound = mid
                if is_first:
                    end = mid - 1  # Look on the left side
                else:
                    start = mid + 1  # Look on the right side
            elif nums[mid] < target:
                start = mid + 1
            else:
                end = mid - 1

        return bound

    first_position = find_bound(nums, target, True)
    last_position = find_bound(nums, target, False)

    return [first_position, last_position] if first_position != -1 else [-1, -1]

