def pacific_atlantic(heights):
    if not heights or not heights[0]:
        return []

    m, n = len(heights), len(heights[0])

    def dfs(i, j, visited, prev_height):
        if (i < 0 or i >= m or j < 0 or j >= n or
                (i, j) in visited or heights[i][j] < prev_height):
            return
        visited.add((i, j))
        for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            dfs(i + direction[0], j + direction[1], visited, heights[i][j])

    pacific_reachable = set()
    atlantic_reachable = set()

    for r in range(m):
        dfs(r, 0, pacific_reachable, heights[r][0])
        dfs(r, n - 1, atlantic_reachable, heights[r][n - 1])

    for c in range(n):
        dfs(0, c, pacific_reachable, heights[0][c])
        dfs(m - 1, c, atlantic_reachable, heights[m - 1][c])

    return list(pacific_reachable & atlantic_reachable)

def longest_palindromic_substring(s):
    """
    Returns the length of the longest palindromic substring in the given string s.
    """
    if not s:
        return 0

    n = len(s)
    # Initialize the table to store intermediate results
    dp = [[False] * n for _ in range(n)]

    max_length = 1

    for i in range(n):
        dp[i][i] = True

    start = 0

    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = True
            start = i
            max_length = 2

    for k in range(3, n+1):
        for i in range(n - k + 1):
            j = i + k - 1

            if dp[i+1][j-1] and s[i] == s[j]:
                dp[i][j] = True

                if k > max_length:
                    start = i
                    max_length = k

    return max_length

