def min_drones(packages, maxWeight):
    """
    Returns the minimum number of drones required to deliver all the packages with the given max weight constraint.
    """
    packages.sort(reverse=True)  # Sort packages in descending order
    num_drones = 0
    while packages:
        current_weight = 0
        i = 0
        while i < len(packages):
            if current_weight + packages[i] <= maxWeight:
                current_weight += packages.pop(i)
            else:
                i += 1
        num_drones += 1
    return num_drones

def min_replacements_to_palindrome(s):
    """
    Returns the minimum number of replacements needed to make s a palindrome.
    """
    n = len(s)
    replacements = 0
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            replacements += 1
    return replacements

