def longestSubstringWithKDistinct(text, k):
    """
    Returns the length of the longest substring of `text` that contains at most `k` distinct characters.
    """
    if k == 0:
        return 0

    char_map = {}
    left = 0
    max_len = 0

    for right in range(len(text)):
        char = text[right]
        if char in char_map:
            char_map[char] += 1
        else:
            char_map[char] = 1

        while len(char_map) > k:
            left_char = text[left]
            char_map[left_char] -= 1
            if char_map[left_char] == 0:
                del char_map[left_char]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

