from collections import defaultdict

def find_representative(graph, char):
    # Find the representative parent of the character
    if graph[char] != char:
        graph[char] = find_representative(graph, graph[char])
    return graph[char]

def union(graph, a, b):
    # Union the sets based on two characters a and b
    rep_a = find_representative(graph, a)
    rep_b = find_representative(graph, b)
    if rep_a != rep_b:
        graph[rep_b] = rep_a  # union the sets

def num_similar_groups(words, equiv):
    # Create a union-find structure to manage equivalence groups
    graph = {}

    for word in words:
        for char in word:
            graph[char] = char  # initially every character is its own parent

    for a, b in equiv:
        union(graph, a, b)  # union the characters in the same group

    # Using set for equivalence classes of each word
    equiv_classes = set()

    for word in words:
        # Find the representative for each character in the word
        rep_word = ''.join(sorted(find_representative(graph, char) for char in word))
        equiv_classes.add(rep_word)

    return len(equiv_classes)

