def is_bipartite(n, edges):
    """
    Determines if the graph represented by n nodes and edges is bipartite.
    """
    from collections import deque

    # Create adjacency list
    adj_list = {i: [] for i in range(n)}
    for a, b in edges:
        adj_list[a].append(b)
        adj_list[b].append(a)

    # Array to store colors, None means uncolored
    color = [None] * n

    def bfs(start):
        queue = deque([start])
        color[start] = 0  # Start coloring with color 0

        while queue:
            node = queue.popleft()
            current_color = color[node]
            for neighbour in adj_list[node]:
                if color[neighbour] is None:
                    # Assign alternate color
                    color[neighbour] = 1 - current_color
                    queue.append(neighbour)
                elif color[neighbour] == current_color:
                    # Neighbor has the same color, not bipartite
                    return False
        return True

    # Check each component of the graph
    for node in range(n):
        if color[node] is None:
            if not bfs(node):
                return False

    return True

