def min_operations_to_non_decreasing(heights):
    """
    Returns the minimum number of operations needed to make the array `heights` non-decreasing.
    """
    operations = 0
    for i in range(1, len(heights)):
        if heights[i] < heights[i - 1]:
            operations += (heights[i - 1] - heights[i])
            heights[i] = heights[i - 1]
    return operations

