def findMedianSortedArrays(nums1, nums2):
    """
    Finds the median of two sorted arrays.
    """
    def find_kth(nums1, s1, nums2, s2, k):
        if s1 >= len(nums1):
            return nums2[s2 + k - 1]
        if s2 >= len(nums2):
            return nums1[s1 + k - 1]
        if k == 1:
            return min(nums1[s1], nums2[s2])

        mid1 = float('inf') if s1 + k // 2 - 1 >= len(nums1) else nums1[s1 + k // 2 - 1]
        mid2 = float('inf') if s2 + k // 2 - 1 >= len(nums2) else nums2[s2 + k // 2 - 1]

        if mid1 < mid2:
            return find_kth(nums1, s1 + k // 2, nums2, s2, k - k // 2)
        else:
            return find_kth(nums1, s1, nums2, s2 + k // 2, k - k // 2)

    m, n = len(nums1), len(nums2)
    total_len = m + n
    if total_len % 2 == 1:
        return find_kth(nums1, 0, nums2, 0, total_len // 2 + 1)
    else:
        return (find_kth(nums1, 0, nums2, 0, total_len // 2) + find_kth(nums1, 0, nums2, 0, total_len // 2 + 1)) / 2.0

from typing import List

def islandPerimeter(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    perimeter = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                # Check top
                if r == 0 or grid[r-1][c] == 0:
                    perimeter += 1
                # Check bottom
                if r == rows-1 or grid[r+1][c] == 0:
                    perimeter += 1
                # Check left
                if c == 0 or grid[r][c-1] == 0:
                    perimeter += 1
                # Check right
                if c == cols-1 or grid[r][c+1] == 0:
                    perimeter += 1

    return perimeter

