def checkDistances(s, distance):
    """
    Returns True if the string `s` is valid according to the `distance` array, else returns False.
    """
    # Dictionary to keep track of the first position of each character.
    char_positions = {}

    for i, char in enumerate(s):
        if char in char_positions:
            # Calculate the distance between the two occurrences
            expected_distance = distance[ord(char) - ord('a')]
            actual_distance = i - char_positions[char] - 1
            if actual_distance != expected_distance:
                return False
        else:
            char_positions[char] = i

    return True

