def check_possibility(nums):
    """
    Returns true if the array nums can be made non-decreasing by modifying at most 
    one element, otherwise returns false.
    """
    n = len(nums)
    count = 0

    for i in range(n - 1):
        if nums[i] > nums[i + 1]:
            count += 1
            if count > 1:
                return False
            if i - 1 >= 0 and nums[i - 1] > nums[i + 1]:
                nums[i + 1] = nums[i] # Modify nums[i+1] to nums[i]
            else:
                nums[i] = nums[i + 1] # Modify nums[i] to nums[i+1]

    return True

