def longest_sign_in_duration(logs):
    """
    Determine the longest continuous duration for which any user was signed-in.

    :param logs: List of log strings with format "<action> <user_id> <timestamp>"
    :return: Tuple (user_id, duration)
    """
    sign_in_time = {}
    durations = {}

    for log in logs:
        action, user_id, timestamp = log.split()
        timestamp = int(timestamp)

        if action == "sign-in":
            sign_in_time[user_id] = timestamp
        elif action == "sign-out" and user_id in sign_in_time:
            duration = timestamp - sign_in_time[user_id]
            if user_id in durations:
                durations[user_id] = max(durations[user_id], duration)
            else:
                durations[user_id] = duration
            del sign_in_time[user_id]

    max_duration = -1
    result_user = None

    for user_id in durations:
        if durations[user_id] > max_duration:
            max_duration = durations[user_id]
            result_user = user_id

    return (result_user, max_duration)

def find_and_replace_pattern(words, pattern):
    def matches(word):
        if len(word) != len(pattern):
            return False
        w_to_p = {}
        p_to_w = {}
        for w, p in zip(word, pattern):
            if w not in w_to_p:
                w_to_p[w] = p
            if p not in p_to_w:
                p_to_w[p] = w
            if w_to_p[w] != p or p_to_w[p] != w:
                return False
        return True

    return [word for word in words if matches(word)]

def find(parent, i):
    # A utility function to find the parent of an element i
    if parent[i] == i:
        return i
    else:
        return find(parent, parent[i])

def union(parent, rank, x, y):
    # A utility function to do union of two subsets x and y
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def kruskal_mst(edges, n):
    result = []  # This will store the resultant MST
    parent = []
    rank = []

    i = 0  # An index variable, used for sorted edges
    e = 0  # An index variable, used for result[]

    for node in range(n):
        parent.append(node)
        rank.append(0)

    edges = sorted(edges, key=lambda item: item[2])

    while e < n - 1:
        if i >= len(edges):
            return -1  # If edges are exhausted and we didn't find enough edges for MST

        u, v, w = edges[i]
        i = i + 1
        x = find(parent, u)
        y = find(parent, v)

        if x != y:
            e = e + 1
            result.append([u, v, w])
            union(parent, rank, x, y)

    minimumCost = 0
    for u, v, weight in result:
        minimumCost += weight
    return minimumCost

