def longest_jump_sequence(arr, d):
    """
    Returns the longest sequence of jumps in the array such that each jump increment the current value by d.

    :param arr: List of distinct integers
    :param d: Integer jump value
    :return: Length of the longest sequence of jumps
    """
    index_map = {val: idx for idx, val in enumerate(arr)}
    max_length = 0

    def find_sequence_length(idx, current_length):
        nonlocal max_length
        next_value = arr[idx] + d

        if next_value in index_map:
            find_sequence_length(index_map[next_value], current_length + 1)
        else:
            max_length = max(max_length, current_length + 1)

    for i in range(len(arr)):
        find_sequence_length(i, 0)

    return max_length

