def is_one_edit_away(s, t):
    """
    Returns True if string s can be transformed into string t by performing at most one edit.
    An edit is defined as: inserting a character, removing a character, or replacing a character.
    """
    len_s = len(s)
    len_t = len(t)

    # If the length difference is more than 1, more than one edit is required
    if abs(len_s - len_t) > 1:
        return False

    # When the lengths are the same, we can only replace one character
    if len_s == len_t:
        edit_required = False
        for i in range(len_s):
            if s[i] != t[i]:
                if edit_required:
                    return False
                edit_required = True
        return True

    # When the lengths differ by one, we can only insert or remove one character
    if len_s > len_t:
        return check_one_edit_insert_remove(t, s)
    return check_one_edit_insert_remove(s, t)

def check_one_edit_insert_remove(shorter, longer):
    """
    Returns True if shorter can be transformed into longer by inserting or removing exactly one character.
    """
    i, j = 0, 0
    edit_required = False
    while i < len(shorter) and j < len(longer):
        if shorter[i] != longer[j]:
            if edit_required:
                return False
            edit_required = True
            j += 1  # skip one character in the longer string
        else:
            i += 1
            j += 1
    return True

