def isIsomorphic(s1, s2):
    """
    Determine if two strings s1 and s2 are isomorphic.
    """
    if len(s1) != len(s2):
        return False

    # Dictionaries to store mappings of characters
    s1_to_s2_mapping = {}
    s2_to_s1_mapping = {}

    for c1, c2 in zip(s1, s2):
        if c1 in s1_to_s2_mapping:
            if s1_to_s2_mapping[c1] != c2:
                return False
        else:
            s1_to_s2_mapping[c1] = c2

        if c2 in s2_to_s1_mapping:
            if s2_to_s1_mapping[c2] != c1:
                return False
        else:
            s2_to_s1_mapping[c2] = c1

    return True

def longest_word(words, queries):
    """
    Returns an array of the lengths of the longest words in `words` that start with `prefix`
    and end with `suffix` for each query in `queries`.
    """
    result = []
    for prefix, suffix in queries:
        max_length = -1
        for word in words:
            if word.startswith(prefix) and word.endswith(suffix):
                max_length = max(max_length, len(word))
        result.append(max_length)
    return result

