def longest_increasing_path(elevations):
    """
    Returns the length of the longest increasing path in the given elevations list.
    """
    if not elevations:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(elevations)):
        if elevations[i] >= elevations[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

