def smallestSubsequence(s: str) -> str:
    last_occurrence = {ch: i for i, ch in enumerate(s)}
    stack = []
    added = set()

    for i, ch in enumerate(s):
        if ch in added:
            continue
        while stack and ch < stack[-1] and i < last_occurrence[stack[-1]]:
            removed = stack.pop()
            added.remove(removed)
        stack.append(ch)
        added.add(ch)

    return ''.join(stack)

