def maxProfit(k, profits):
    """
    Returns the maximum profit that can be achieved by making at most k transactions.

    :param k: The maximum number of transactions allowed.
    :param profits: A list of non-negative integers representing the daily profits.
    :return: The maximum profit.
    """
    if not profits or k == 0:
        return 0

    n = len(profits)

    if k >= n // 2:
        return sum(x - y for x, y in zip(profits[1:], profits[:-1]) if x > y)

    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -profits[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j - 1], profits[j] + max_diff)
            max_diff = max(max_diff, dp[i - 1][j] - profits[j])

    return dp[k][-1]

