def num_regions_above_threshold(grid, threshold):
    """
    Returns the number of distinct regions in the grid where all cells have elevations greater or equal to the threshold.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or visited[x][y] or grid[x][y] < threshold:
            return
        visited[x][y] = True
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    regions = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] >= threshold and not visited[i][j]:
                regions += 1
                dfs(i, j)

    return regions

