def trap(height):
    """
    Computes the maximum amount of water that can be trapped between the heights.

    Args:
    height (List[int]): A list of non-negative integers representing the height of various points.

    Returns:
    int: Maximum amount of water that can be trapped.
    """
    if not height:
        return 0

    n = len(height)
    left, right = 0, n - 1
    left_max, right_max = 0, 0
    water_trapped = 0

    while left < right:
        if height[left] < height[right]:
            if height[left] >= left_max:
                left_max = height[left]
            else:
                water_trapped += left_max - height[left]
            left += 1
        else:
            if height[right] >= right_max:
                right_max = height[right]
            else:
                water_trapped += right_max - height[right]
            right -= 1

    return water_trapped

