def count_pairs_with_sum(arr, target):
    """
    Returns the number of unique pairs of integers in the list that sum up to the target value.
    """
    seen = set()
    pairs = set()
    for num in arr:
        compliment = target - num
        if compliment in seen:
            pairs.add(tuple(sorted([num, compliment])))
        seen.add(num)
    return len(pairs)

