def minimize_subset_sum_difference(nums, k):
    """
    Distributes the numbers into k non-empty subsets such that the difference
    between the maximum sum of any subset and the minimum sum of any subset is minimized.

    Parameters:
    nums (list of int): List of non-negative integers.
    k (int): The number of subsets to divide into.

    Returns:
    int: The minimized difference between the maximum and minimum subset sums.
    """
    if not nums or k == 0:
        return 0

    total_sum = sum(nums)
    def possible_to_divide(target):
        partitions = [0] * k
        nums.sort(reverse=True)

        def backtrack(index):
            if index == len(nums):
                return True
            for i in range(k):
                if partitions[i] + nums[index] <= target:
                    partitions[i] += nums[index]
                    if backtrack(index + 1):
                        return True
                    partitions[i] -= nums[index]
                if partitions[i] == 0:
                    break
            return False

        return backtrack(0)

    left, right = max(nums), total_sum
    while left < right:
        mid = (left + right) // 2
        if possible_to_divide(mid):
            right = mid
        else:
            left = mid + 1

    return left

