def minimum_calorie_difference(foods, targetCalories):
    """
    Returns the minimum difference between the total calories of the chosen 
    meal plan and targetCalories.

    :param foods: List[int], list of calories of each food item
    :param targetCalories: int, the target calorie intake
    :return: int, the minimum difference
    """
    n = len(foods)
    total_calories = sum(foods)

    dp = [[False] * (total_calories + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(total_calories + 1):
            if dp[i - 1][j]:
                dp[i][j] = True
                if j + foods[i - 1] <= total_calories:
                    dp[i][j + foods[i - 1]] = True

    min_diff = float('inf')
    for s in range(total_calories + 1):
        if dp[n][s]:
            min_diff = min(min_diff, abs(targetCalories - s))

    return min_diff

