def check_sorted(words):
    """
    Checks if the given list of words is sorted in lexicographical order.
    Returns -1 if the list is sorted.
    Returns the indices of the first pair of words which are out of order if the list is not sorted.
    """
    for i in range(len(words) - 1):
        if words[i] > words[i + 1]:
            return [i, i + 1]
    return -1

