def longest_substring_with_k_distinct(s, k):
    """
    Returns the length of the longest substring with at most k distinct letters.

    :param s: A string consisting of lowercase English letters
    :param k: An integer representing the limit on the number of distinct letters
    :return: The length of the longest substring with at most k distinct letters
    """
    if k == 0 or not s:
        return 0

    char_map = {}
    left = 0
    max_length = 0

    for right in range(len(s)):
        char = s[right]
        if char in char_map:
            char_map[char] += 1
        else:
            char_map[char] = 1

        while len(char_map) > k:
            left_char = s[left]
            char_map[left_char] -= 1
            if char_map[left_char] == 0:
                del char_map[left_char]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

def min_days_to_unique_heights(trees):
    """
    Determines the minimum number of days required to ensure that no two adjacent trees have the same height.
    If it’s not possible to achieve this condition, returns -1.
    """
    # Early low-length check cases
    if not trees:
        return 0
    if len(trees) == 1:
        return 0

    days = 0
    n = len(trees)

    # Check for each tree if it can be removed to satisfy the condition
    i = 0
    while i < len(trees) - 1:
        if trees[i] == trees[i + 1]:
            days += 1
            if i + 2 < n:
                trees.pop(i + 1)
            else:
                trees.pop(i)
        else:
            i += 1

    # Verify all adjacent trees have different heights (final check)
    for i in range(1, len(trees)):
        if trees[i] == trees[i - 1]:
            return -1

    return days

