def longest_prefix_word(words):
    """
    Returns the longest word in `words` that is a prefix of at least one other word in `words`.
    If there are multiple such words of the same length, returns the one that appears first.
    If no such word exists, returns an empty string.
    """
    words_set = set(words)
    longest_word = ""

    for word in words:
        for i in range(1, len(word)):
            if word[:i] in words_set:
                if len(word[:i]) > len(longest_word):
                    longest_word = word[:i]
                elif len(word[:i]) == len(longest_word):
                    longest_word = word[:i] if words.index(word[:i]) < words.index(longest_word) else longest_word

    return longest_word

