def min_removals_to_satisfy_limit(heights, limit):
    n = len(heights)
    if n == 0:
        return 0

    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if abs(heights[i] - heights[j]) <= limit:
                dp[i] = max(dp[i], dp[j] + 1)

    max_valid_length = max(dp)
    return n - max_valid_length

