def minSubarrayLength(nums, target):
    total_sum = sum(nums)

    # If the total sum is already equal to the target
    if total_sum == target:
        return 0

    subarray_sum_needed = total_sum - target
    if subarray_sum_needed < 0:
        return -1

    left = 0
    current_sum = 0
    min_length = float('inf')

    for right in range(len(nums)):
        current_sum += nums[right]

        while current_sum > subarray_sum_needed and left <= right:
            current_sum -= nums[left]
            left += 1

        if current_sum == subarray_sum_needed:
            min_length = min(min_length, right - left + 1)

    return min_length if min_length != float('inf') else -1

def are_one_swap_away(s1, s2):
    """
    Determines if two strings can be made identical with at most one character swap.
    """
    if s1 == s2:
        return True

    diff_indices = []
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            diff_indices.append(i)
            if len(diff_indices) > 2:
                return False

    if len(diff_indices) != 2:
        return False

    i, j = diff_indices
    return s1[i] == s2[j] and s1[j] == s2[i]

