def multiply_strings(s1, s2):
    """
    Multiplies two large non-negative integers represented as strings.
    """
    if s1 == "0" or s2 == "0":
        return "0"

    len1, len2 = len(s1), len(s2)
    result = [0] * (len1 + len2)

    s1 = s1[::-1]
    s2 = s2[::-1]

    for i in range(len1):
        for j in range(len2):
            result[i + j] += int(s1[i]) * int(s2[j])
            result[i + j + 1] += result[i + j] // 10
            result[i + j] %= 10

    while len(result) > 1 and result[-1] == 0:
        result.pop()

    return ''.join(map(str, result[::-1]))

