def maxSumNonAdjacent(nums):
    """
    Given an integer array nums, return the maximum sum obtainable by selecting non-adjacent elements.
    """
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return max(0, nums[0])

    # dp[i] will store the maximum sum of non-adjacent elements from nums[0] to nums[i]
    dp = [0] * n
    dp[0] = max(0, nums[0])
    dp[1] = max(dp[0], nums[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + nums[i])

    return dp[-1]

def find_peak(arr):
    """
    Returns the index of a peak element in the array.

    :param arr: List[int] - The input array representing a mountain.
    :return: int - Index of one of the peak elements.
    """
    if not arr:
        return -1

    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2
        if arr[mid] < arr[mid + 1]:
            left = mid + 1
        else:
            right = mid

    return left

