def subset_sum(arr, k):
    """
    Determine if there is a subset of the array `arr` that sums to `k`.
    :param arr: List of distinct integers
    :param k: Target sum to find in the subsets of `arr`
    :return: True if a subset with sum `k` exists, otherwise False
    """
    n = len(arr)
    dp = [[False] * (k + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if arr[i-1] <= j:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    return dp[n][k]

