def min_swaps_to_group_ones(data):
    """
    Returns the minimum number of swaps required to group all 1's together in the array.
    """
    n = len(data)
    total_ones = sum(data)

    if total_ones == 0 or total_ones == n:
        return 0

    max_ones_in_window = 0
    current_ones_in_window = 0

    for i in range(total_ones):
        if data[i] == 1:
            current_ones_in_window += 1

    max_ones_in_window = current_ones_in_window

    for i in range(total_ones, n):
        if data[i] == 1:
            current_ones_in_window += 1
        if data[i - total_ones] == 1:
            current_ones_in_window -= 1
        max_ones_in_window = max(max_ones_in_window, current_ones_in_window)

    return total_ones - max_ones_in_window

