def find_anagrams(s, t):
    from collections import Counter

    result = []
    t_counter = Counter(t)
    window_counter = Counter(s[:len(t) - 1])

    for i in range(len(t) - 1, len(s)):
        start_index = i - len(t) + 1
        window_counter[s[i]] += 1

        if window_counter == t_counter:
            result.append(start_index)

        window_counter[s[start_index]] -= 1
        if window_counter[s[start_index]] == 0:
            del window_counter[s[start_index]]

    return sorted(result)

def max_subarray_len(nums, k):
    """
    Returns the maximum length of a subarray that sums to k.

    :param nums: List[int] - List of integers
    :param k: int - Target sum
    :return: int - Maximum length of subarray that sums to k
    """
    sum_map = {}
    curr_sum = 0
    max_len = 0

    for i in range(len(nums)):
        curr_sum += nums[i]
        if curr_sum == k:
            max_len = i + 1
        if (curr_sum - k) in sum_map:
            max_len = max(max_len, i - sum_map[curr_sum - k])
        if curr_sum not in sum_map:
            sum_map[curr_sum] = i

    return max_len

