def lenLongestFibSubseq(arr):
    """
    Returns the length of the longest Fibonacci-like subsequence of arr.
    If no such sequence exists, return 0.
    """
    if len(arr) < 3:
        return 0

    indices = {x: i for i, x in enumerate(arr)}
    longest = {}
    max_len = 0

    for k in range(len(arr)):
        for j in range(k):
            if arr[k] - arr[j] in indices and indices[arr[k] - arr[j]] < j:
                i = indices[arr[k] - arr[j]]
                if (i, j) in longest:
                    longest[j, k] = longest[i, j] + 1
                else:
                    longest[j, k] = 3
                max_len = max(max_len, longest[j, k])

    return max_len

