def sumOfSubtreeValues(tree, values, queries):
    from collections import defaultdict, deque

    def bfs_calculate_subtree_sums(n, tree, values):
        graph = defaultdict(list)
        for u, v in tree:
            graph[u].append(v)
            graph[v].append(u)

        subtree_sum = [0] * (n + 1)
        visited = [False] * (n + 1)

        def dfs(node):
            visited[node] = True
            current_sum = values[node - 1]
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    current_sum += dfs(neighbor)
            subtree_sum[node] = current_sum
            return current_sum

        for i in range(1, n + 1):
            if not visited[i]:
                dfs(i)

        return subtree_sum

    n = len(values)
    subtree_sum = bfs_calculate_subtree_sums(n, tree, values)

    result = []
    for query in queries:
        result.append(subtree_sum[query])

    return result

