def rob(nums):
    """
    Given an array of integers representing the amount of money at each house,
    this function returns the maximum amount of money you can rob without alerting the police.
    """
    if not nums:
        return 0
    elif len(nums) == 1:
        return nums[0]
    elif len(nums) == 2:
        return max(nums[0], nums[1])

    prev1, prev2 = nums[0], max(nums[0], nums[1])

    for i in range(2, len(nums)):
        current = max(prev1 + nums[i], prev2)
        prev1 = prev2
        prev2 = current

    return prev2

