from itertools import combinations

def max_influence_of_clique(m, influences, connections, k):
    graph = {i: set() for i in range(1, m + 1)}

    for u, v in connections:
        graph[u].add(v)
        graph[v].add(u)

    max_influence = -1
    nodes = list(range(1, m + 1))

    for clique in combinations(nodes, k):
        if all(v in graph[u] for u, v in combinations(clique, 2)):
            max_influence = max(max_influence, sum(influences[i - 1] for i in clique))

    return max_influence

