import math

def smallest_divisor(arr, threshold):
    def get_sum_of_divisions(divisor):
        return sum(math.ceil(x / divisor) for x in arr)

    low, high = 1, max(arr)
    while low < high:
        mid = (low + high) // 2
        if get_sum_of_divisions(mid) > threshold:
            low = mid + 1
        else:
            high = mid
    return low

from itertools import combinations

def longest_unique_string_length(words, k):
    """
    Returns the length of the longest string that can be formed by concatenating exactly k words
    from the list `words` such that no letter occurs more than once in the string.
    If it's not possible to form such a string, returns 0.
    """
    def is_unique(s):
        return len(s) == len(set(s))

    max_length = 0
    for combo in combinations(words, k):
        combined = ''.join(combo)
        if is_unique(combined):
            max_length = max(max_length, len(combined))

    return max_length

