from typing import List

def has_one_on_diagonal(grid: List[List[int]]) -> bool:
    """
    Checks if there is at least one "1" on the main diagonal of the matrix.
    """
    n = len(grid)
    for i in range(n):
        if grid[i][i] == 1:
            return True
    return False

def remove_invalid_parentheses(s):
    """
    Remove the minimum number of parentheses to make the input string valid.
    """

    def remove_invalid(s, open_paren, close_paren):
        balance = 0
        result = []

        for char in s:
            if char == open_paren:
                balance += 1
            elif char == close_paren:
                if balance == 0:
                    continue
                balance -= 1
            result.append(char)

        return ''.join(result)

    # 1st pass to remove invalid closing parentheses
    result = remove_invalid(s, '(', ')')
    # 2nd pass to remove invalid opening parentheses in the reversed string
    result = remove_invalid(result[::-1], ')', '(')

    return result[::-1]

