def min_moves_to_balance_parentheses(s):
    open_count = 0
    close_needed = 0

    for char in s:
        if char == '(':
            open_count += 1
        else:
            if open_count == 0:
                close_needed += 1
            else:
                open_count -= 1

    return open_count + close_needed

