def has_cycle(graph, n):
    """
    Determines if there exists a cycle that includes the vertex `n`.

    :param graph: List[List[int]] - The adjacency list of the directed graph.
    :param n: int - The vertex to check for a cycle inclusion.
    :return: bool - True if a cycle includes vertex `n`, False otherwise.
    """
    visited = [False] * len(graph)
    rec_stack = [False] * len(graph)

    def dfs(v):
        visited[v] = True
        rec_stack[v] = True

        for neighbor in graph[v]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[v] = False
        return False

    return dfs(n)

