def longest_subsequence(nums, d):
    """
    Returns the length of the longest subsequence such that the difference between
    consecutive elements is exactly `d` in the given integer array `nums`.
    """
    if not nums:
        return 0

    # Dictionary to store the length of subsequence ending with the value of the key
    dp = {}

    max_len = 0

    for num in nums:
        if num - d in dp:
            dp[num] = dp[num - d] + 1
        else:
            dp[num] = 1

        max_len = max(max_len, dp[num])

    return max_len

