def max_substring_occurrences(sequence, k):
    """
    Determines the maximum number of times any substring of length k appears in the given sequence.

    Args:
    sequence (str): The DNA sequence composed of 'A', 'C', 'G', 'T'.
    k (int): The length of the substrings to consider.

    Returns:
    int: The maximum number of times any substring of length k appears in the sequence.
    """
    if len(sequence) < k:
        return 0

    substring_count = {}
    for i in range(len(sequence) - k + 1):
        substring = sequence[i:i+k]
        if substring in substring_count:
            substring_count[substring] += 1
        else:
            substring_count[substring] = 1

    return max(substring_count.values())

