def mergeAlternately(word1, word2):
    """
    Returns a string by merging two input strings alternately. 
    If one string is longer than the other, append the additional characters of the longer string at the end.
    """
    merged_string = []
    len1, len2 = len(word1), len(word2)
    max_len = max(len1, len2)

    for i in range(max_len):
        if i < len1:
            merged_string.append(word1[i])
        if i < len2:
            merged_string.append(word2[i])

    return ''.join(merged_string)

