def isValidSudoku(board):
    """
    Check if a given 9x9 Sudoku board is valid.

    :param board: List[List[str]] - 9x9 2D list representing the Sudoku board
    :return: bool - True if the board is valid, False otherwise
    """
    def is_valid_unit(unit):
        unit = [i for i in unit if i != '.']
        return len(unit) == len(set(unit))

    # Check rows
    for row in board:
        if not is_valid_unit(row):
            return False

    # Check columns
    for col in zip(*board):
        if not is_valid_unit(col):
            return False

    # Check 3x3 sub-boxes
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            sub_box = [board[x][y] for x in range(i, i + 3) for y in range(j, j + 3)]
            if not is_valid_unit(sub_box):
                return False

    return True

