def minimum_moves_to_sort(heights):
    """
    Returns the minimum number of moves required to sort the list in increasing order by height.
    """
    sorted_heights = sorted(heights)
    lcs_length = longest_common_subsequence(heights, sorted_heights)
    return len(heights) - lcs_length

def longest_common_subsequence(array1, array2):
    """
    Helper function to find the length of the longest common subsequence between two arrays.
    """
    m, n = len(array1), len(array2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if array1[i - 1] == array2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

