def smallestStringWithSwaps(s, pairs):
    from collections import defaultdict

    parent = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    # Initialize the union-find structure
    for i in range(len(s)):
        parent[i] = i

    # Applying union operations for each pair
    for x, y in pairs:
        union(x, y)

    # Grouping indices by their root parent
    groups = defaultdict(list)
    for i in range(len(s)):
        root = find(i)
        groups[root].append(i)

    # Forming the smallest possible string by sorting each group
    s = list(s)
    for group in groups.values():
        indices = sorted(group)
        characters = sorted(s[i] for i in group)
        for ind, char in zip(indices, characters):
            s[ind] = char

    return ''.join(s)

