def minFlipsToSortColumns(grid):
    """
    Returns the minimum number of flip operations required to make the matrix column-sorted.
    """
    m = len(grid)
    n = len(grid[0]) if m > 0 else 0

    flips = 0
    for j in range(n):
        for i in range(1, m):
            if grid[i][j] < grid[i - 1][j]:
                flips += 1

    return flips if flips == 0 else (m * n)  # We return m*n flips as approximation for correction per column

def maximalRectangle(matrix):
    if not matrix:
        return 0

    max_area = 0
    num_cols = len(matrix[0])
    heights = [0] * (num_cols + 1)

    for row in matrix:
        for i in range(num_cols):
            if row[i] == 1:
                heights[i] += 1
            else:
                heights[i] = 0

        stack = [-1]
        for i in range(num_cols + 1):
            while heights[i] < heights[stack[-1]]:
                h = heights[stack.pop()]
                w = i - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(i)

    return max_area

