def min_steps_to_meet(grid):
    def bfs(start_row, start_col):
        queue = deque([(start_row, start_col, 0)])  # (row, col, steps)
        visited = [[False for _ in range(n)] for _ in range(m)]
        visited[start_row][start_col] = True
        steps_grid = [[float('inf') for _ in range(n)] for _ in range(m)]
        steps_grid[start_row][start_col] = 0

        while queue:
            row, col, steps = queue.popleft()
            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < m and 0 <= new_col < n and not visited[new_row][new_col] and grid[new_row][new_col] != 1:
                    visited[new_row][new_col] = True
                    queue.append((new_row, new_col, steps + 1))
                    steps_grid[new_row][new_col] = steps + 1
        return steps_grid

    m, n = len(grid), len(grid[0])
    people_positions = [(i, j) for i in range(m) for j in range(n) if grid[i][j] == 2]

    if not people_positions:
        return -1

    if len(people_positions) == 1:
        return 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    all_steps_grids = [bfs(row, col) for row, col in people_positions]

    min_steps = float('inf')
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                continue
            total_steps = sum(steps_grid[i][j] for steps_grid in all_steps_grids if steps_grid[i][j] != float('inf'))
            if all(steps_grid[i][j] != float('inf') for steps_grid in all_steps_grids):
                min_steps = min(min_steps, total_steps)

    return -1 if min_steps == float('inf') else min_steps

