def count_prefix_compatible_pairs(words):
    """
    Returns the number of prefix-compatible pairs in the given list of strings.

    Args:
    words (list): List of strings

    Returns:
    int: Number of prefix-compatible pairs (A, B) where A is a prefix of B and A != B
    """

    def is_prefix(small, large):
        return large.startswith(small)

    count = 0
    n = len(words)

    for i in range(n):
        for j in range(n):
            if i != j and is_prefix(words[i], words[j]):
                count += 1

    return count

