def length_of_longest_distinct_substring(s, k):
    if k == 0:
        return 0

    n = len(s)
    left = 0
    right = 0
    char_count = {}
    max_len = 0
    distinct_count = 0

    while right < n:
        char = s[right]
        if char not in char_count or char_count[char] == 0:
            distinct_count += 1
        char_count[char] = char_count.get(char, 0) + 1

        while distinct_count > k:
            left_char = s[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                distinct_count -= 1
            left += 1

        max_len = max(max_len, right - left + 1)

        right += 1

    return max_len

