def checkPossibility(nums):
    """
    Determines if the array can be made non-decreasing by modifying at most one element.

    Parameters:
    nums (List[int]): The input array of integers.

    Returns:
    bool: True if the array can be made non-decreasing by modifying at most one element, otherwise False.
    """
    one_change_allowed = True

    for i in range(1, len(nums)):
        if nums[i] < nums[i - 1]:
            if not one_change_allowed:
                return False
            one_change_allowed = False

            if i == 1 or nums[i - 2] <= nums[i]:
                nums[i - 1] = nums[i]  # modify nums[i - 1]
            else:
                nums[i] = nums[i - 1]  # modify nums[i]

    return True

