def can_construct_target(words, target):
    """
    Returns True if target can be constructed by concatenating any subsequence of the strings in words.
    Returns False otherwise.
    """
    # Mapping characters in target to their frequencies
    target_char_count = {}
    for char in target:
        if char in target_char_count:
            target_char_count[char] += 1
        else:
            target_char_count[char] = 1

    # Mapping characters in words list to their frequencies
    words_char_count = {}
    for word in words:
        for char in word:
            if char in words_char_count:
                words_char_count[char] += 1
            else:
                words_char_count[char] = 1

    # Check if all characters in target can be formed by characters in words
    for char, count in target_char_count.items():
        if words_char_count.get(char, 0) < count:
            return False

    return True

