def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring in s.
    """
    stack = []
    max_length = 0
    last_invalid_index = -1

    for index, char in enumerate(s):
        if char in "([{":
            stack.append((char, index))
        else:
            if stack and ((stack[-1][0] == '(' and char == ')') or
                          (stack[-1][0] == '[' and char == ']') or
                          (stack[-1][0] == '{' and char == '}')):
                stack.pop()
                if stack:
                    max_length = max(max_length, index - stack[-1][1])
                else:
                    max_length = max(max_length, index - last_invalid_index)
            else:
                last_invalid_index = index

    return max_length

