from collections import Counter

def leastInterval(tasks, n):
    """
    Calculate the least number of units of times that the CPU will take to finish all the given tasks.
    """
    if n == 0:
        return len(tasks)

    task_counts = Counter(tasks)
    max_tasks = max(task_counts.values())
    max_count_task_occurrences = sum(1 for task in task_counts.values() if task == max_tasks)

    slots = (max_tasks - 1) * (n + 1) + max_count_task_occurrences

    return max(len(tasks), slots)

