def findMaxLength(arr):
    """
    Finds the length of the longest subarray with an equal number of 0s and 1s.

    The approach is based on using a hashmap to store (count, index) pairs.

    Parameters:
    arr (list): The input array containing only 0s and 1s.

    Returns:
    int: The length of the longest subarray with equal number of 0s and 1s.
    """
    count_map = {0: -1}
    max_length = 0
    count = 0

    for i, num in enumerate(arr):
        if num == 0:
            count -= 1
        else:
            count += 1

        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length

