def max_subarray_profit(arr):
    """
    Returns the maximum profit that can be made from a contiguous subarray of the given array of profits (and losses).
    Implements Kadane's algorithm to find the maximum sum subarray in O(n) time complexity.
    """
    if not arr:
        return 0

    max_current = max_global = arr[0]

    for profit in arr[1:]:
        max_current = max(profit, max_current + profit)
        if max_current > max_global:
            max_global = max_current

    return max_global

