def min_swaps_to_palindrome(s):
    """
    Returns the minimum number of adjacent swaps needed to make the string a palindrome.
    If it is not possible to form a palindrome, returns -1.
    """
    def is_palindrome_possible(s):
        odd_count = sum(freq % 2 for freq in Counter(s).values())
        return odd_count <= 1

    def min_swaps_needed(l):
        swaps = 0
        for i in range(len(l)//2):
            left = i
            right = len(l) - left - 1
            while left < right:
                if l[left] == l[right]:
                    break
                else:
                    right -= 1
            if left == right:
                l[left], l[left + 1] = l[left + 1], l[left]
                swaps += 1
                continue
            for j in range(right, len(l) - left - 1):
                l[j], l[j + 1] = l[j + 1], l[j]
                swaps += 1
        return swaps

    from collections import Counter
    if not is_palindrome_possible(s):
        return -1

    s_list = list(s)
    return min_swaps_needed(s_list)

def can_transform(s, t):
    """
    Determines if string s can be transformed into string t by performing exactly one 
    of these operations: insert one character, delete one character, or replace one character.
    """

    len_s, len_t = len(s), len(t)

    # Case 1: Insert one character (len_s + 1 == len_t)
    if len_s + 1 == len_t:
        for i in range(len_t):
            if s[:i] + t[i] + s[i:] == t:
                return True

    # Case 2: Delete one character (len_s - 1 == len_t)
    elif len_s - 1 == len_t:
        for i in range(len_s):
            if s[:i] + s[i+1:] == t:
                return True

    # Case 3: Replace one character (len_s == len_t)
    elif len_s == len_t:
        difference_count = 0
        for i in range(len_s):
            if s[i] != t[i]:
                difference_count += 1
            if difference_count > 1:
                return False
        return difference_count == 1

    return False

def find_pairs_with_sum(numbers, target):
    """
    Find all unique pairs (a, b) in the list 'numbers' such that a + b = target.
    Each pair (a, b) should be in non-decreasing order and the resulting list of pairs should be sorted.
    """
    pairs = set()
    seen = set()

    for number in numbers:
        complement = target - number
        if complement in seen:
            pairs.add((min(number, complement), max(number, complement)))
        seen.add(number)

    return sorted(pairs)

